import { cn } from "@/lib/utils"

// Stand-in: declares @tabler/icons-react but imports nothing from it; palette classes for surfaces.
export function BentoGrid({ className, children }: { className?: string; children?: React.ReactNode }) {
  return <div className={cn("grid gap-4 md:grid-cols-3", className)}>{children}</div>
}

export function BentoGridItem({ className, title, icon }: { className?: string; title?: React.ReactNode; icon?: React.ReactNode }) {
  return (
    <div className={cn("flex flex-col gap-2 rounded-xl border border-neutral-200 bg-white p-4 dark:border-neutral-800 dark:bg-black", className)}>
      {icon}
      <div className="font-medium text-neutral-700 dark:text-neutral-200">{title}</div>
    </div>
  )
}
